window.VO = [{"id":"n01","text":"You're the only witness to this crash.","at":0.24,"t0":0.12,"t1":1.865},{"id":"n02","text":"Watch closely.","at":4.17,"t0":2.085,"t1":3.04},{"id":"n03","text":"The driver doesn't stop.","at":10.38,"t0":5.19,"t1":6.635},{"id":"n04","text":"So you're all this man has.","at":13.87,"t0":6.935,"t1":8.32},{"id":"n05","text":"How fast was the rickshaw going when it smashed into the cart?","at":19.84,"t0":9.92,"t1":13.01},{"id":"n06","text":"And the broken glass: left of the cart, or right?","at":29.12,"t0":14.56,"t1":17.39},{"id":"n07","text":"There was no broken glass.","at":40.78,"t0":20.39,"t1":21.86},{"id":"n08","text":"Go back and look.","at":44.62,"t0":22.31,"t1":23.33},{"id":"n09","text":"He never asked if there was any.","at":48.86,"t0":24.43,"t1":26.19},{"id":"n10","text":"He asked where it was.","at":52.98,"t0":26.49,"t1":27.765},{"id":"n11","text":"And some of you could almost see it.","at":56.53,"t0":28.265,"t1":29.83},{"id":"n12","text":"Because your brain doesn't replay a memory.","at":60.26,"t0":30.13,"t1":32.26},{"id":"n13","text":"It rebuilds it, every time, with whatever it's just heard.","at":65.02,"t0":32.51,"t1":35.74},{"id":"n14","text":"Even one word can do it.","at":72.58,"t0":36.29,"t1":37.885},{"id":"n15","text":"In nineteen seventy-four, students whose question said smashed, not hit, were twice as likely, a week later, to remember broken glass.","at":76.37,"t0":38.185,"t1":46.14},{"id":"n16","text":"There wasn't any.","at":92.98,"t0":46.49,"t1":47.56},{"id":"n17","text":"That's why judges usually stop questions like his.","at":96.22,"t0":48.11,"t1":51},{"id":"n18","text":"Out here, nobody did.","at":102.6,"t0":51.3,"t1":52.65},{"id":"n19","text":"So if you picked a side, the police are now looking for broken glass.","at":106.1,"t0":53.05,"t1":56.86},{"id":"n20","text":"His glass is fine.","at":114.42,"t0":57.21,"t1":58.4},{"id":"n21","text":"Said there wasn't any? Good.","at":120.3,"t0":60.15,"t1":61.74},{"id":"n22","text":"What hit his windscreen?","at":124.28,"t0":62.14,"t1":63.47}];
